style.css:
@-moz-document domain("youtube.com"), url("https://www.youtube.com/") {
/* Make all text black */
    * {
        color: black !important;
    }

    /* Video title */
    h1.title, 
    h1.ytd-watch-metadata, 
    #container h1, 
    yt-formatted-string.title {
        color: black !important;
    }

    /* Video metadata (views, likes, etc.) */
    #info-text, 
    #count, 
    #owner-name, 
    .ytd-video-owner-renderer, 
    .ytd-video-primary-info-renderer {
        color: black !important;
    }

    /* Comments section */
    #content-text, 
    #author-text, 
    .ytd-comment-renderer, 
    .ytd-expander {
        color: black !important;
    }

    /* Video descriptions */
    #description, 
    .ytd-video-secondary-info-renderer {
        color: black !important;
    }

    /* Recommended video titles */
    #video-title, 
    #video-title-link, 
    .ytd-compact-video-renderer, 
    .ytd-thumbnail-overlay-time-status-renderer {
        color: black !important;
    }

    /* Sidebar and menus */
    #guide-inner-content, 
    #guide-title, 
    #sections, 
    .ytd-guide-section-renderer, 
    .ytd-guide-entry-renderer {
        color: black !important;
    }
}
